// Format angka Indonesia: pemisah ribuan titik, desimal koma.
export function fmt(value, format) {
  if (value === null || value === undefined) return '—';
  const id = (n, d = 0) =>
    n.toLocaleString('id-ID', { minimumFractionDigits: d, maximumFractionDigits: d });
  switch (format) {
    case 'orang':
      return id(value);
    case 'miliar-usd':
      return `US$${id(value, 2)} miliar`;
    case 'usd':
      return `US$${id(value)}`;
    case 'persen':
      return `${id(value, 2)}%`;
    case 'tahun':
      return `${id(value, 1)} tahun`;
    default:
      return id(value, 2);
  }
}

// Angka ringkas untuk kartu dan sumbu grafik (mis. 283,5 jt).
export function fmtShort(value, format) {
  if (value === null || value === undefined) return '—';
  const id = (n, d = 0) =>
    n.toLocaleString('id-ID', { minimumFractionDigits: d, maximumFractionDigits: d });
  switch (format) {
    case 'orang':
      return `${id(value / 1e6, 1)} jt`;
    case 'miliar-usd':
      return `${id(value, 0)}`;
    case 'usd':
      return `${id(value)}`;
    case 'persen':
      return `${id(value, 2)}%`;
    case 'tahun':
      return `${id(value, 1)}`;
    default:
      return id(value, 2);
  }
}
