.switcher button[aria-pressed="true"] { background: var(--accent); border-color: var(--accent); color: var(--accent-ink); font-weight: 700; }

/* ---- tabel ---- */
table.data { width: 100%; border-collapse: collapse; background: var(--card); font-size: 15.5px; }
table.data th, table.data td { padding: 9px 10px; border-bottom: 1px solid var(--line); text-align: right; font-variant-numeric: tabular-nums; }
table.data th:first-child, table.data td:first-child { text-align: left; }
table.data thead th { background: var(--ink); color: #f2efe4; font-size: 14px; }
table.data thead th:first-child { border-radius: 8px 0 0 0; }
table.data thead th:last-child { border-radius: 0 8px 0 0; }
table.data tbody tr:hover { background: var(--accent-soft); }
table.data tbody tr.hl td { background: #f3e9c8; font-weight: 700; }
.table-scroll { overflow-x: auto; border-radius: 8px; margin: 12px 0; }
table.data td.neg { color: #b3541e; font-weight: 700; }

/* ---- kontrol halaman data ---- */
.controls { display: flex; gap: 12px; flex-wrap: wrap; align-items: end; margin: 18px 0 6px; }
.controls label { font-size: 14px; font-weight: 700; display: block; margin-bottom: 4px; }
.controls input[type="search"], .controls select {
  font: inherit; font-size: 15.5px; padding: 9px 12px; border: 1px solid var(--line);
  border-radius: 8px; background: var(--card); color: var(--ink); min-width: 220px;
}
.btn {
  font: inherit; font-size: 15.5px; font-weight: 700; padding: 9px 16px; border-radius: 8px;
  border: 1px solid var(--accent); background: var(--accent); color: var(--accent-ink); cursor: pointer;
}
.btn:hover { filter: brightness(1.08); }
.btn.ghost { background: var(--card); color: var(--accent); }

/* ---- daftar & sorotan ---- */
.findings { display: grid; grid-template-columns: repeat(3, 1fr); gap: 14px; margin: 14px 0; }
.finding { background: var(--card); border: 1px solid var(--line); border-left: 5px solid var(--accent); border-radius: var(--radius); padding: 14px 16px; }
.finding p { margin: 4px 0 0; font-size: 15px; }
.finding .big { font-size: 24px; font-weight: 800; letter-spacing: -.4px; }
.explore { display: grid; grid-template-columns: repeat(2, 1fr); gap: 14px; margin: 14px 0; }
.explore a {
  background: var(--card); border: 1px solid var(--line); border-radius: var(--radius);
  padding: 16px 18px; text-decoration: none; color: var(--ink); display: block;
}
.explore a:hover { border-color: var(--accent); }
.explore a h3 { color: var(--accent); }
.explore a p { margin: 4px 0 0; font-size: 15px; color: var(--ink-soft); }
.sources { font-size: 14.5px; }
.sources li { margin-bottom: 6px; }
.callout { background: var(--accent-soft); border-radius: var(--radius); padding: 14px 18px; margin: 18px 0; }
.callout p { margin: 0; }

/* ---- footer ---- */
.site-footer { border-top: 1px solid var(--line); padding: 26px 0 34px; font-size: 14.5px; color: var(--ink-soft); }
.site-footer p { margin: 6px 0; }

/* ---- telepon ---- */
@media (max-width: 760px) {
  body { font-size: 16px; }
  h1 { font-size: 27px; }
  h2 { font-size: 20px; }
  .header-inner { gap: 4px; }
  .site-nav { margin-left: 0; overflow-x: auto; flex-wrap: nowrap; width: 100%; padding-bottom: 8px; }
  .site-nav a { white-space: nowrap; }
  .cards, .findings { grid-template-columns: 1fr; }
  .explore { grid-template-columns: 1fr; }
  .card .value { font-size: 26px; }
  .controls input[type="search"], .controls select { min-width: 0; width: 100%; }
}
